alter table profiles add column if not exists whatsapp_number text;
create table if not exists admin_activity_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references profiles(id) on delete set null,action text not null,entity_type text,entity_id text,description text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists payments(id uuid primary key default gen_random_uuid(),student_id uuid references profiles(id),title text not null,amount numeric(12,2) not null default 0,status text default 'pending',payment_method text,paid_at timestamptz,created_at timestamptz default now());
create table if not exists invoices(id uuid primary key default gen_random_uuid(),student_id uuid references profiles(id),invoice_number text unique not null,amount numeric(12,2) not null default 0,status text default 'unpaid',due_date date,created_at timestamptz default now());
alter table admin_activity_logs enable row level security;alter table payments enable row level security;alter table invoices enable row level security;
create policy activity_super_admin_read on admin_activity_logs for select using(app_role()='super_admin');
create policy activity_authenticated_insert on admin_activity_logs for insert with check(actor_id=auth.uid());
create policy payments_admin on payments for all using(app_role() in('super_admin','admin_staff')) with check(app_role() in('super_admin','admin_staff'));
create policy invoices_admin on invoices for all using(app_role() in('super_admin','admin_staff')) with check(app_role() in('super_admin','admin_staff'));
create or replace function record_admin_change() returns trigger language plpgsql security definer set search_path=public as $$begin if auth.uid() is not null then insert into admin_activity_logs(actor_id,action,entity_type,entity_id,description) values(auth.uid(),lower(tg_op),tg_table_name,coalesce(new.id,old.id)::text,initcap(lower(tg_op))||' action on '||replace(tg_table_name,'_',' '));end if;return coalesce(new,old);end$$;
do $$declare t text;begin foreach t in array array['profiles','courses','categories','enrollments','live_sessions','announcements','support_tickets','support_faqs','email_templates','calendar_appointments','payments','invoices'] loop execute format('drop trigger if exists audit_change on %I',t);execute format('create trigger audit_change after insert or update or delete on %I for each row execute function record_admin_change()',t);end loop;end$$;
